import sys

def occurrences(pat, t):
    n, m = len(t), len(pat)
    res = [False] * (n + 1)
    if m == 0:
        return [True] * (n + 1)
    s = pat + '#' + t
    L = len(s)
    z = [0] * L
    l = r = 0
    for i in range(1, L):
        if i < r:
            z[i] = min(r - i, z[i - l])
        while i + z[i] < L and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] > r:
            l, r = i, i + z[i]
    for i in range(n - m + 1):
        if z[m + 1 + i] >= m:
            res[i] = True
    return res

def main():
    data = sys.stdin.read().split()
    t, p = data[0], data[1]
    k = p.index('*')
    a, b = p[:k], p[k + 1:]
    n = len(t)
    la, lb = len(a), len(b)
    oa = occurrences(a, t)
    ob = occurrences(b, t)
    # cnt[x] = number of start positions i of a with i + la <= x
    cnt = [0] * (n + 2)
    run = 0
    for x in range(n + 1):
        i = x - la
        if i >= 0 and oa[i] and i <= n - la:
            run += 1
        cnt[x] = run
    total = 0
    for s in range(n - lb + 1):
        if ob[s] and s >= la:
            total += cnt[s]
    print(total)

main()

